<?php
declare(strict_types=1);
namespace TempNumber;
interface ProductProvider {
 public function catalogue(string $product):array;
 public function quote(string $product,array $request,?array $resource):array;
 public function fulfil(string $intent,string $operation,array $quote,?array $resource):array;
 public function messages(string $providerId):array;
 public function message(string $providerId,string $messageId):array;
 public function delete(string $providerId):bool;
 public function action(string $providerId,string $action):array;
 public function findIntent(string $intent):array;
}
final class UnconfiguredProductProvider implements ProductProvider {
 private function unavailable():never {fail('PROVIDER_UNAVAILABLE','The provider is not connected. No new funds have been charged.',503);}
 public function catalogue(string $product):array {$this->unavailable();}
 public function quote(string $product,array $request,?array $resource):array {$this->unavailable();}
 public function fulfil(string $intent,string $operation,array $quote,?array $resource):array {throw new AmbiguousProvisioning('Provider unavailable.');}
 public function messages(string $providerId):array {$this->unavailable();}
 public function message(string $providerId,string $messageId):array {$this->unavailable();}
 public function delete(string $providerId):bool {$this->unavailable();}
 public function action(string $providerId,string $action):array {$this->unavailable();}
 public function findIntent(string $intent):array {$this->unavailable();}
}
require_once __DIR__.'/RewardAccounting.php';
final class Commerce {
 public static function adapter(string $product):ProductProvider {if($product==='long-term'){require_once __DIR__.'/TextVerifiedRentalProvider.php';return new TextVerifiedRentalProvider();}if($product==='smm'){require_once __DIR__.'/SmmProvider.php';return new SmmProvider();}return new UnconfiguredProductProvider();}
 public static function price(string $product,array $quote):int {if($product==='temp-mail'){$v=env('TEMP_MAIL_PRICE_CENTS');if(!ctype_digit($v)||(int)$v<1)fail('PRICING_UNCONFIGURED','Inbox pricing requires configuration.',503);return (int)$v;}$config=Pricing::setting($product.'_pricing');if(!$config||($quote['currency']??'')!==$config['currency'])fail('PRICING_UNCONFIGURED','Billing currency and pricing require configuration.',503);return Pricing::quote((int)$quote['cost_minor'],$config,'retail',$product==='smm');}
 public static function quote(string $product,array $input):array {self::table($product);required($input,'service',120);if($product==='smm')$input['_preview']=true;$q=self::adapter($product)->quote($product,$input,null);if($product==='smm'){if(filter_var($input['quantity']??null,FILTER_VALIDATE_INT)===false||(int)$input['quantity']<(int)$q['minimum']||(int)$input['quantity']>(int)$q['maximum'])fail('INVALID_QUANTITY','Quantity is outside the supported range.');}return ['currency'=>'USD','price_usd'=>money(self::price($product,$q))];}
 public static function table(string $product):string {return match($product){'temp-mail'=>'inboxes','smm'=>'smm_orders','long-term','dedicated'=>'orders',default=>throw new Problem('INVALID_PRODUCT','Unknown product.')};}
 public static function owned(string $product,string $id,string $uid):array {$table=self::table($product);$row=one('SELECT * FROM '.$table.' WHERE id=? AND user_id=?',[$id,$uid]);if(!$row||($table==='orders'&&$row['product']!==$product))fail('NOT_FOUND','Resource not found.',404);return $row;}
 public static function fulfil(array $u,string $product,string $operation,array $input,string $key,?ProductProvider $adapterOverride=null):array {
  if($product==='long-term'&&!isset($input['max_price_usd']))fail('PRICE_REQUIRED','Check the rental price before purchase.');if(!in_array($operation,['purchase','renewal'],true))fail('INVALID_OPERATION','Unsupported operation.');if($key===''||strlen($key)>100)fail('IDEMPOTENCY_REQUIRED','A valid Idempotency-Key is required.');self::table($product);unset($input['_preview'],$input['_provider_quote']);$resource=$operation==='renewal'?self::owned($product,required($input,'id',32),$u['id']):null;
  if($product==='smm'){require_once __DIR__.'/SmmProvider.php';$input['target']=SmmProvider::validateTarget(required($input,'target',2048));$target=$input['target'];if(!filter_var($target,FILTER_VALIDATE_URL)||!in_array(parse_url($target,PHP_URL_SCHEME),['http','https'],true))fail('INVALID_TARGET','Enter a valid HTTP or HTTPS target link.');if(!isset($input['quantity'])||filter_var($input['quantity'],FILTER_VALIDATE_INT)===false||(int)$input['quantity']<1)fail('INVALID_QUANTITY','Enter a positive whole quantity.');}
  if($resource&&$product!=='long-term'){$key='renew:'.$resource['id'].':'.($resource['expires_at']??'none');if(!isset($input['max_price_usd']))$input['max_price_usd']=money((int)$resource['price_cents']);}$request=['product'=>$product,'operation'=>$operation,'input'=>$input];ksort($request['input']);$hash=hash('sha256',json_encode($request));$existing=one('SELECT * FROM fulfilment_intents WHERE user_id=? AND idempotency_key=?',[$u['id'],$key]);if($existing){if($existing['request_hash']!==$hash)fail('IDEMPOTENCY_CONFLICT','This operation key has different input.',409);return self::result($existing);}
  $adapter=$adapterOverride??self::adapter($product);$quote=$adapter->quote($product,$input,$resource);
  if($product==='smm'&&((int)$input['quantity']<(int)$quote['minimum']||(int)$input['quantity']>(int)$quote['maximum']))fail('INVALID_QUANTITY','Quantity is outside the provider-supported limits.');
  $price=self::price($product,$quote);if($price<1)fail('PRICING_UNCONFIGURED','The final selling price is invalid.',503);if(isset($input['max_price_usd'])&&$price>cents($input['max_price_usd']))fail('PRICE_EXCEEDS_MAX','The quote exceeds your maximum price.');
  $id=id();$intent=tx(function()use($id,$u,$product,$operation,$resource,$hash,$key,$price,$input,$quote){one('SELECT user_id FROM wallets WHERE user_id=?'.lockSuffix(),[$u['id']]);if($product==='long-term'&&$resource&&one("SELECT id FROM fulfilment_intents WHERE resource_id=? AND product='long-term' AND operation='renewal' AND status IN ('pending','reconciliation') AND idempotency_key<>?",[$resource['id'],$key]))fail('RENEWAL_PENDING','An extension is already awaiting confirmation. Check its status before extending again.',409);$existing=one('SELECT * FROM fulfilment_intents WHERE user_id=? AND idempotency_key=?',[$u['id'],$key]);if($existing){if($existing['request_hash']!==$hash)fail('IDEMPOTENCY_CONFLICT','This operation key has different input.',409);return $existing;}Wallet::change($u['id'],'reservation',0,'commerce-reserve:'.$id,'Reserve '.$product.' '.$operation,$price);query('INSERT INTO fulfilment_intents (id,user_id,product,operation,resource_id,request_hash,idempotency_key,price_cents,status,request_payload,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$u['id'],$product,$operation,$resource['id']??null,$hash,$key,$price,'pending',json_encode(array_merge($input,['_provider_quote'=>$quote])),now(),now()]);return one('SELECT * FROM fulfilment_intents WHERE id=?',[$id]);});if($intent['id']!==$id)return self::result($intent);RewardAccounting::record($id,$u['id'],$resource['id']??$id,$product,'commerce-capture:'.$id,$quote,Pricing::setting($product.'_pricing')??[]);
  try{$receipt=$adapter->fulfil($id,$operation,$quote,$resource);if(empty($receipt['id']))throw new AmbiguousProvisioning('No provider receipt');query('UPDATE fulfilment_intents SET receipt=?,updated_at=? WHERE id=?',[json_encode($receipt),now(),$id]);self::activate($id,$receipt,$input);}
  catch(Problem $error){if($error instanceof ProviderRejected||$error instanceof NumberProviderRejected||in_array($error->key,['PROVIDER_RATE_LIMITED'],true)){tx(function()use($id){$intent=one('SELECT * FROM fulfilment_intents WHERE id=?'.lockSuffix(),[$id]);if($intent['status']!=='pending')return;Wallet::change($intent['user_id'],'release',0,'commerce-release:'.$id,'Provider rejected submission',-(int)$intent['price_cents']);query("UPDATE fulfilment_intents SET status='rejected',updated_at=? WHERE id=?",[now(),$id]);audit('fulfilment_rejected',$intent['user_id'],['intent'=>$id]);});}else{query("UPDATE fulfilment_intents SET status='reconciliation',updated_at=? WHERE id=? AND status='pending'",[now(),$id]);audit('fulfilment_reconciliation',$u['id'],['intent'=>$id]);}}
  catch(\Throwable){query("UPDATE fulfilment_intents SET status='reconciliation',updated_at=? WHERE id=? AND status='pending'",[now(),$id]);audit('fulfilment_reconciliation',$u['id'],['intent'=>$id]);}
  return self::result(one('SELECT * FROM fulfilment_intents WHERE id=?',[$id]));
 }
 public static function activate(string $id,array $receipt,array $input):void {tx(function()use($id,$receipt,$input){$i=one('SELECT * FROM fulfilment_intents WHERE id=?'.lockSuffix(),[$id]);if(!$i)fail('NOT_FOUND','Intent not found.',404);if($i['status']==='completed')return;if(!in_array($i['status'],['pending','reconciliation'],true))fail('INTENT_CLOSED','This intent is already closed.',409);$price=(int)$i['price_cents'];$rid=$i['resource_id']??id();$product=$i['product'];if($i['operation']==='renewal'){if(empty($receipt['expires_at']))throw new AmbiguousProvisioning('No renewal expiry');query('UPDATE '.self::table($product).' SET expires_at=?,status=? WHERE id=? AND user_id=?',[$receipt['expires_at'],'active',$rid,$i['user_id']]);}elseif($product==='temp-mail'){if(!filter_var($receipt['address']??'',FILTER_VALIDATE_EMAIL)||empty($receipt['expires_at']))throw new AmbiguousProvisioning('No inbox address or expiry');query('INSERT INTO inboxes (id,user_id,provider_id,address,status,price_cents,expires_at,created_at) VALUES (?,?,?,?,?,?,?,?)',[$rid,$i['user_id'],$receipt['id'],$receipt['address'],'active',$price,$receipt['expires_at'],now()]);}elseif($product==='smm'){query('INSERT INTO smm_orders (id,user_id,provider_order_id,service,target,quantity,price_cents,status,created_at) VALUES (?,?,?,?,?,?,?,?,?)',[$rid,$i['user_id'],$receipt['id'],$input['service'],$input['target'],(int)$input['quantity'],$price,'pending',now()]);query('UPDATE smm_orders SET service_name=?,refill_supported=?,updated_at=? WHERE id=?',[$receipt['service_name']??$input['service'],!empty($receipt['refill'])?1:0,now(),$rid]);}else{if(empty($receipt['phone'])||empty($receipt['expires_at']))throw new AmbiguousProvisioning('No number or expiry');query('INSERT INTO orders (id,user_id,provider,provider_order_id,product,service,phone,status,price_cents,price_tier,idempotency_key,request_hash,expires_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$rid,$i['user_id'],$receipt['provider']??'getatext',$receipt['id'],$product,$input['service']??'dedicated',$receipt['phone'],'active',$price,'retail','commerce:'.$id,$i['request_hash'],$receipt['expires_at'],now(),now()]);}if($product==='long-term')query('UPDATE orders SET rental_duration=?,rental_refundable=?,rental_details_href=COALESCE(?,rental_details_href),auto_renew=0 WHERE id=?',[$receipt['duration']??$input['duration']??null,!empty($receipt['refundable'])?1:0,$receipt['details_href']??null,$rid]);RewardAccounting::receipt($id,$receipt,$rid);Wallet::change($i['user_id'],$i['operation']==='renewal'?'renewal':'purchase',-$price,'commerce-capture:'.$id,$product.' '.$i['operation'],-$price);query("UPDATE fulfilment_intents SET status='completed',resource_id=?,updated_at=? WHERE id=?",[$rid,now(),$id]);});}
 public static function result(array $i):array {return ['id'=>$i['id'],'resource_id'=>$i['resource_id'],'status'=>$i['status'],'price_usd'=>money((int)$i['price_cents']),'currency'=>'USD'];}
 public static function synchronise(string $product,array $resource,string $action='status',?ProductProvider $adapterOverride=null):array {if($product==='long-term'&&$resource['provider']!=='textverified')fail('PROVIDER_UNAVAILABLE','This historical rental uses a different provider.',503);$providerId=$resource['provider_order_id']??$resource['provider_id']??null;if(!$providerId)fail('PROVISIONING_PENDING','Provisioning has not yet been confirmed.',409);$result=($adapterOverride??self::adapter($product))->action($providerId,$action);if(empty($result['authoritative']))fail('UNCONFIRMED_OUTCOME','Provider confirmation is required.',409);$state=$result['status']??'reconciliation';if(!in_array($state,['pending','active','completed','partial','cancelled','expired','reconciliation'],true))$state='reconciliation';return tx(function()use($product,$resource,$result,$state){$table=self::table($product);$row=one('SELECT * FROM '.$table.' WHERE id=?'.lockSuffix(),[$resource['id']]);if(in_array($row['status'],['cancelled','expired','completed'],true)&&!($product==='long-term'&&$row['status']==='expired')&&$state!==$row['status'])return ['status'=>$row['status']];if(!empty($result['financial_final'])&&isset($result['refund_cents'])){$refund=$result['refund_cents'];if(!is_int($refund)||$refund<0||$refund>(int)$row['price_cents'])fail('INVALID_PROVIDER_OUTCOME','Provider refund requires reconciliation.',409);if($refund>0)Wallet::change($row['user_id'],'refund',$refund,'commerce-refund:'.$product.':'.$resource['id'],'Confirmed wallet refund');}query('UPDATE '.$table.' SET status=? WHERE id=?',[$state,$resource['id']]);if($product==='smm')foreach(all('SELECT source_id FROM reward_costs WHERE resource_id=?',[$resource['id']])as$cost)RewardAccounting::receipt($cost['source_id'],$result);if($state==='completed'||($product==='long-term'&&$state==='expired'))RewardAccounting::completed($resource['id']);if($product==='long-term')query('UPDATE orders SET expires_at=COALESCE(?,expires_at),rental_refundable=?,updated_at=? WHERE id=?',[$result['expires_at']??null,!empty($result['refundable'])?1:0,now(),$row['id']]);if($product==='smm')query('UPDATE smm_orders SET start_count=?,remaining=? WHERE id=?',[$result['start_count']??$row['start_count'],$result['remaining']??$row['remaining'],$resource['id']]);return ['status'=>$state,'message'=>'Provider status confirmed.'];});}
}
